import markSvg from './assets/brand/mark.svg' with { type: 'text' }
import wordmarkSvg from './assets/brand/wordmark.svg' with { type: 'text' }
import avatarSvg from './assets/brand/avatar.svg' with { type: 'text' }
import { mixHex } from './theme'

// Jefi's mark is an envelope with a letter rising out of it; artwork lives in assets/ and is
// regenerated by `bun run brand`. Both vectors are one colour, so GPUI tints them to the theme.

/** An SVG's drawing size, read from its viewBox so these never drift from the artwork. */
function viewBoxSize(svg: string) {
  const [, , width, height] = svg.match(/viewBox="([^"]+)"/)![1]!.split(/\s+/).map(Number)
  return { width: width!, height: height! }
}

/** The mark's proportions: a little wider than tall. */
export const MARK_SIZE = viewBoxSize(markSvg)
const WORDMARK_SIZE = viewBoxSize(wordmarkSvg)

/** The app-icon tile as an image URL, for places a full-colour avatar is needed. */
export const JEFI_AVATAR = `data:image/svg+xml;base64,${Buffer.from(avatarSvg).toString('base64')}`

// avatar.svg is a white tile with the mark in the brand violet; the mark's gradient stops derive
// from it (scripts/brand.ts), so swapping them recolours it to an accent.
const BRAND_INK = '#8B5CF6'
const avatarByAccent = new Map<string, string>()

/** The app-icon tile in `accent`, matching the Dock icon. */
export function jefiAvatar(accent: string): string {
  let url = avatarByAccent.get(accent)
  if (!url) {
    const svg = avatarSvg
      .replaceAll(mixHex(BRAND_INK, '#FFFFFF', 0.2), mixHex(accent, '#FFFFFF', 0.2))
      .replaceAll(mixHex(BRAND_INK, '#000000', 0.12), mixHex(accent, '#000000', 0.12))
    url = `data:image/svg+xml;base64,${Buffer.from(svg).toString('base64')}`
    avatarByAccent.set(accent, url)
  }
  return url
}

/** The mark alone, fitted to a `size` × `size` square (it is wider than tall, so `size` is its width). */
export function JefiMark({ size, color }: { size: number; color: string }) {
  const height = (size * MARK_SIZE.height) / MARK_SIZE.width
  return <svg source={markSvg} style={{ width: size, height, flexShrink: 0, color, pointerEvents: 'none' }} />
}

/** The logo (the mark, or a lockup when assets/logo.svg exists), sized by height. */
export function JefiWordmark({ height, color }: { height: number; color: string }) {
  const width = (height * WORDMARK_SIZE.width) / WORDMARK_SIZE.height
  return <svg source={wordmarkSvg} style={{ width, height, flexShrink: 0, color, pointerEvents: 'none' }} />
}
